<?php
declare(strict_types=1);
session_start(['cookie_httponly'=>true,'cookie_secure'=>true,'cookie_samesite'=>'Lax','use_strict_mode'=>true]);
header('X-Content-Type-Options: nosniff');header('Referrer-Policy: same-origin');header('Content-Security-Policy: default-src \'self\'; style-src \'self\' \'unsafe-inline\'; form-action \'self\'; base-uri \'none\'');
function esc($x):string{return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function db():PDO {
 $path=getenv('SHIPWREKT_CREW_DB');
 if(!$path||!str_starts_with($path,'/')||str_contains($path,'/public_html/')||str_contains($path,'/htdocs/'))throw new RuntimeException('Crew enrollment is not configured yet.');
 $dir=dirname($path);if(!is_dir($dir))throw new RuntimeException('Crew storage unavailable.');
 $db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
 $db->exec('CREATE TABLE IF NOT EXISTS engineers(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,callsign TEXT NOT NULL,experience TEXT NOT NULL DEFAULT \'\',specialties TEXT NOT NULL DEFAULT \'\',timezone TEXT NOT NULL DEFAULT \'UTC\',languages TEXT NOT NULL DEFAULT \'\',availability TEXT NOT NULL DEFAULT \'\',status TEXT NOT NULL DEFAULT \'pending\',agreement_version TEXT,agreement_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');
 return $db;
}
function token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function formToken():string{return '<input type="hidden" name="csrf" value="'.esc(token()).'">';}
$error='';$notice='';$db=null;
try{$db=db();}catch(Throwable $e){$error='Engineer enrollment is being prepared. Applications are not open yet.';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!$db){http_response_code(503);}
 elseif(!hash_equals(token(),(string)($_POST['csrf']??''))){$error='Session expired. Reload and try again.';}
 else{
 $action=(string)($_POST['action']??'');
 try{
 if($action==='register'){
  $email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$callsign=trim((string)($_POST['callsign']??''));
  if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||strlen($password)>256||mb_strlen($callsign)>60||mb_strlen($callsign)<3)throw new RuntimeException('Enter a valid email, a 3 to 60 character callsign and a password of at least 12 characters.');
  if(empty($_POST['agreement']))throw new RuntimeException('You must acknowledge the applicant terms.');
  $q=$db->prepare('INSERT INTO engineers(email,password_hash,callsign,agreement_version,agreement_at) VALUES(?,?,?,?,datetime(\'now\'))');
  $q->execute([$email,password_hash($password,PASSWORD_DEFAULT),$callsign,'applicant-v1']);
  session_regenerate_id(true);$_SESSION['engineer_id']=(int)$db->lastInsertId();$notice='Application account created. Complete your profile. Approval is required before public listing.';
 }elseif($action==='login'){
  $q=$db->prepare('SELECT id,password_hash FROM engineers WHERE email=?');$q->execute([strtolower(trim((string)($_POST['email']??'')))]);$user=$q->fetch();
  if(!$user||!password_verify((string)($_POST['password']??''),$user['password_hash']))throw new RuntimeException('Invalid credentials.');
  session_regenerate_id(true);$_SESSION['engineer_id']=(int)$user['id'];$notice='Signed in.';
 }elseif($action==='logout'){unset($_SESSION['engineer_id']);session_regenerate_id(true);$notice='Signed out.';}
 elseif($action==='profile'&&!empty($_SESSION['engineer_id'])){
  $fields=['callsign'=>60,'experience'=>600,'specialties'=>350,'timezone'=>70,'languages'=>160,'availability'=>1200];$v=[];
  foreach($fields as $key=>$max){$value=trim((string)($_POST[$key]??''));if(mb_strlen($value)>$max)throw new RuntimeException('Profile field too long: '.$key);$v[]=$value;}
  if(!in_array($v[3],timezone_identifiers_list(),true))throw new RuntimeException('Choose a valid IANA timezone, for example Asia/Bangkok.');
  if(mb_strlen($v[0])<3)throw new RuntimeException('Callsign must have at least 3 characters.');
  $v[]=(int)$_SESSION['engineer_id'];$q=$db->prepare('UPDATE engineers SET callsign=?,experience=?,specialties=?,timezone=?,languages=?,availability=? WHERE id=?');$q->execute($v);$notice='Profile saved. Public listing requires SHIPWREKT verification.';
 }else throw new RuntimeException('Invalid request.');
 }catch(Throwable $e){$error='Could not complete request. '.($e instanceof PDOException?'Check whether this email is already registered.':$e->getMessage());}
 }
}
$user=null;if($db&&!empty($_SESSION['engineer_id'])){$q=$db->prepare('SELECT id,callsign,experience,specialties,timezone,languages,availability,status FROM engineers WHERE id=?');$q->execute([(int)$_SESSION['engineer_id']]);$user=$q->fetch();}
$crew=[];if($db){$crew=$db->query("SELECT callsign,experience,specialties,timezone,languages,availability FROM engineers WHERE status='approved' ORDER BY callsign LIMIT 60")->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>The Crew | SHIPWREKT</title><style>body{margin:0;background:#061417;color:#eaf8f6;font:16px/1.6 system-ui,sans-serif}*{box-sizing:border-box}main{max-width:1060px;margin:auto;padding:35px 24px}a{color:#35e6d3}h1{font-size:3rem}h2{color:#35e6d3}.panel{padding:24px;background:#102b2e;border:1px solid #2e6e6c;border-radius:15px;margin:20px 0}label{display:block;margin:13px 0}input,textarea{display:block;width:100%;max-width:700px;padding:12px;background:#071b1d;border:1px solid #4b7b7a;color:#fff;border-radius:7px;font:inherit}input[type=checkbox]{display:inline;width:auto}button{background:#35e6d3;color:#092020;border:0;border-radius:7px;padding:13px 22px;font-weight:800;cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.muted{color:#b1cbca}.warn{color:#ffbd82}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main><a href="/shipwrekt/">☠ SHIPWREKT</a><h1>The Crew</h1><p class="muted">Independent security engineers. Public profiles use callsigns, not personal identities. Applicants must be verified and approved before appearing here.</p><?php if($error):?><p class="warn"><?=esc($error)?></p><?php endif;?><?php if($notice):?><p><?=esc($notice)?></p><?php endif;?><h2>Meet the crew</h2><?php if(!$crew):?><div class="panel"><p>Our crew roster is being assembled. No engineers are publicly listed until their qualifications and agreements have been reviewed.</p></div><?php endif;?><div class="grid"><?php foreach($crew as $member):?><article class="panel"><h2><?=esc($member['callsign'])?></h2><p><?=nl2br(esc($member['experience']))?></p><p><strong>Specialties:</strong> <?=esc($member['specialties'])?></p><p><strong>Timezone:</strong> <?=esc($member['timezone'])?></p><p><strong>Languages:</strong> <?=esc($member['languages'])?></p><p><strong>Availability:</strong> <?=esc($member['availability'])?></p><p class="muted">Booking opens after vetting and scheduling integrations are complete.</p></article><?php endforeach;?></div><h2>Engineer portal</h2><?php if($user):?><div class="panel"><h3>Welcome, <?=esc($user['callsign'])?></h3><p>Application status: <strong><?=esc($user['status'])?></strong></p><form method="post"><?=formToken()?><input type="hidden" name="action" value="profile"><label>Callsign<input name="callsign" required maxlength="60" value="<?=esc($user['callsign'])?>"></label><label>Experience and qualifications<textarea name="experience" rows="4" maxlength="600"><?=esc($user['experience'])?></textarea></label><label>Specialties<textarea name="specialties" rows="3" maxlength="350"><?=esc($user['specialties'])?></textarea></label><label>Timezone (IANA name)<input name="timezone" required maxlength="70" value="<?=esc($user['timezone'])?>"></label><label>Languages<input name="languages" maxlength="160" value="<?=esc($user['languages'])?>"></label><label>General availability (local timezone)<textarea name="availability" rows="3" maxlength="1200"><?=esc($user['availability'])?></textarea></label><button>Save profile</button></form><form method="post"><?=formToken()?><input type="hidden" name="action" value="logout"><button>Sign out</button></form></div><?php else:?><div class="grid"><div class="panel"><h3>Apply to join</h3><p>Applications are reviewed manually. This account does not confer contractor status or authorize work.</p><form method="post"><?=formToken()?><input type="hidden" name="action" value="register"><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Callsign<input name="callsign" minlength="3" maxlength="60" required></label><label>Password (12+ characters)<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label><input type="checkbox" name="agreement" required> I acknowledge this is an application only; contractor engagement requires a separately executed agreement and identity/qualification review.</label><button<?=!$db?' disabled':''?>>Apply</button></form></div><div class="panel"><h3>Engineer sign in</h3><form method="post"><?=formToken()?><input type="hidden" name="action" value="login"><label>Email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button<?=!$db?' disabled':''?>>Sign in</button></form></div></div><?php endif;?><div class="panel"><h2>How crew selection will work</h2><p>Customers will be able to choose an approved engineer by specialty, timezone and availability, or ask the Captain to assign a suitable available specialist. Booking, calendar synchronization, assessments and legally reviewed e-signatures are not active yet.</p><p>Private identities are held for verification and contracting only. Callsigns and approved professional details appear publicly.</p></div></main></body></html>